    [2040] = "从死亡矿井中带回小型高能发动机，将其带给暴风城矮人区中的沉默的舒尼。",
    [2198] = "找到破碎的项链的来源，从而了解其潜在的价值。",
    [2199] = "给铁炉堡的塔瓦斯德·基瑟尔带去五块银锭。",
    [2200] = "去奥达曼寻找塔瓦斯的魔法项链，被杀的圣骑士是最后一个拿着它的人。",
    [2201] = "在奥达曼寻找红宝石、蓝宝石和黄宝石的下落。找到它们之后，通过塔瓦斯德给你的占卜之瓶和他进行联系。",
    [2202] = "收集12颗紫色蘑菇，把它们交给卡加斯的加卡尔。",
    [2204] = "从奥达曼最强大的石人身上获得能量源，然后将其交给铁炉堡的塔瓦斯德。",
    [2240] = "阅读巴尔洛戈的日记，探索密室，然后向铁炉堡的勘察员塔伯斯·雷矛汇报。",
    [2278] = "和石头守护者交谈，从他那里了解更多古代的知识。一旦你了解到了所有的内容之后就激活诺甘农圆盘。",
    [2279] = "把迷你版的诺甘农圆盘带到铁炉堡的探险者协会去。",
    [2280] = "把迷你版的诺甘农圆盘带到雷霆崖的贤者那里。",
    [2283] = "在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。",
    [2284] = "在奥达曼里找寻宝石的线索。",
    [2318] = "在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。",
    [2338] = "将项链借给加卡尔。作为交换，他将帮你翻译日记。",
    [2339] = "从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。$B$B红宝石被藏在暗影矮人层层设防的地区。$B$B黄宝石藏在石腭怪活动地区的一个瓮中。$B$B蓝宝石在格瑞姆洛克手中，他是石腭怪的领袖。$B$B能量源可能在奥达曼的某个最强生物的手中。",
    [2340] = "把项链和宝石送到奥格瑞玛的德兰·杜佛斯那里。",
    [2341] = "去卡加斯看看加卡尔是否成功了。",
    [2342] = "从奥达曼南部大厅的箱子中找到加勒特的家族宝藏，然后把它交给幽暗城的帕特里克·加瑞特。",
    [2359] = "偷取迪菲亚塔楼钥匙，进入迪菲亚塔楼，看看暮色森林的箱子里到底有什么东西，然后向暴风城的马迪亚斯·肖尔汇报。",
    [2360] = "去西部荒野和密探吉尔妮谈一谈。",
    [2361] = "我很高兴能给你这条项链，强大的$C。你对我的帮助是无价的，我为此对你表示万分的感谢。请把它戴上吧，这是属于你的荣耀，请在别人问及的时候告诉他们，是我制作了这条项链！$B$B另外，如果你证明这条项链根本没有受到诅咒，那就更棒了。",
    [2398] = "在奥达曼找到巴尔洛戈。",
    [2418] = "给荒芜之地的里格弗兹带去8块德提亚姆能量石和8块安纳洛姆能量石。",
    [2439] = "把你的报酬凭证交给铁炉堡银行的丁尼塔·石衣。",
    [2440] = "把报酬凭证交给雷霆崖的本娜·冰蹄。",
    [2458] = "到淤泥沼泽北边的风险投资公司塔楼去，联系碎手氏族的卧底费苏勒。$B$B看到塔楼之后，用信号枪发射信号，向工头费苏勒示意你已经到达。发出两个闪光信号，然后使用碎手军礼和工头费苏勒接头。$B$B注意，这些步骤必须依次进行，因为费苏勒会攻击并干掉任何他无法识别的人。",
    [2460] = "对着申苏尔练习碎手军礼。",
    [2478] = "从工头希里克斯那里偷出希里克斯的塔楼钥匙，进入塔楼，然后杀掉两个变异风险投资公司工人、两个风险投资公司巡逻员、两个风险投资公司看守。$B$B杀掉大工头普兹克·加里维克斯，取了他的首级，然后打开加里维克斯的箱子，拿走赞吉尔的改良药剂。将药剂和加里维克斯的头颅交给奥格瑞玛的申苏尔，等候进一步的指示。",
    [2479] = "到希尔斯布莱德丘陵的塔伦米尔去，把赞吉尔的药剂样品交给瑟尔格·希诺特。$B$B要去塔伦米尔，可以搭乘飞艇到幽暗城，然后沿着大路向南穿过银松森林，直到希尔斯布莱德丘陵。跟着路标走！",
    [2480] = "等待瑟尔格·希诺特完成解药。",
    [2607] = "到兵营的地窖里去和道克·米希匹克斯谈一谈。",
    [2608] = "用/lay指令躺下，接受道克·米希匹克斯的治疗。如果他找不到病因，就找不到治疗的方法。",
    [2609] = "给道克·米希匹克斯带去一束普通野花、一只铅瓶，一根青铜管，最后还要一卷淡绿色丝线。伊提斯综合症可不会不治而愈，年轻的$G先生:小姐;。",
    [2621] = "与斯通纳德的分队指挥官鲁尔格谈一谈。",
    [2622] = "与本戈尔谈一谈。",
    [2623] = "取回酋长的命令，把它们还给部落英雄的灵魂。",
    [2681] = "解救九个拉瑟莱克的仆从、三个瑟温妮的仆从、三个奥利斯塔的仆从和三个戈洛尔的仆从。完成任务后，回到部落英雄的灵魂这里。",
    [2701] = "打开箱子，取走你的酬劳。",
    [2702] = "和桑德·裂蹄谈一谈。",
    [2721] = "找到基利斯的下落。",
    [2743] = "回去见部落英雄的灵魂，将你的发现告诉他。",
    [2744] = "与艾萨拉的洛拉姆斯·萨里比迪斯谈一谈。",
    [2745] = "与暴风城堡的泰里恩谈一谈。",
    [2746] = "将3块丝绸和2只克拉拉的新鲜苹果交给暴风城的泰里恩。",
    [2768] = "把探水棒交给加基森的首席工程师沙克斯·比格维兹。",
    [2770] = "把加兹瑞拉的鳞片交给闪光平原的维兹尔·铜栓。",
    [2783] = "与诅咒之地和悲伤沼泽交界处的部落英雄的灵魂谈一谈。",
    [2784] = "聆听部落英雄的灵魂讲述他的故事。",
    [2801] = "聆听部落英雄的灵魂讲述他的故事。",
    [2846] = "将深渊皇冠交给尘泥沼泽的塔贝萨。",
    [2861] = "与尘泥沼泽的塔贝萨谈一谈。",
    [2864] = "与加基森的特兰雷克谈一谈。",
    [2865] = "给加基森的特兰雷克带去5个完整的圣甲虫壳。",
    [2936] = "阅读塞卡石板，了解枯木巨魔的蜘蛛之神的名字，然后回到加德林大师那里。",
    [2983] = "去贫瘠之地找到卡纳尔·菲斯。",
    [2984] = "去贫瘠之地找到卡纳尔·菲斯。",
    [2985] = "找到贫瘠之地的水之先知伊斯伦。",
    [2986] = "找到贫瘠之地的水之先知伊斯伦。",
    [2991] = "将耐克鲁姆的徽章交给诅咒之地的萨迪斯·格希德。",
    [3001] = "在棘齿城找到斯坦哈德·法尔杉。",
    [3042] = "收集20瓶巨魔调和剂，把它们交给加基森的特伦顿·轻锤。",
    [3141] = "听洛拉姆斯·萨里比迪斯讲述他的故事。",
    [3369] = "把噩梦碎片交给长者高地的哈缪尔·符文图腾。",
    [3370] = "把噩梦碎片交给达纳苏斯的玛斯雷·驭熊者。",
    [3373] = "把伊兰尼库斯精华放在精华之泉里，精华之泉就在沉没的神庙中，伊兰尼库斯的巢穴里。",
    [3380] = "到塔纳利斯找到玛尔冯·瑞文斯克。",
    [3446] = "在悲伤沼泽沉没的神庙中找到哈卡祭坛。",
    [3447] = "到沉没的神庙去，揭开雕像群中隐藏的秘密。",
    [3504] = "把这封给阿格图的密信交给艾萨拉的阿格图·血拳。",
    [3505] = "杀死10个血精灵搜寻者和10个血精灵勘测员，并找到大法师雷姆托里的营地。一旦你发现了营地，就去找到某个对她极为重要的东西，以用于激怒她，让她与你战斗。",
    [3508] = "等待洛拉姆斯完成启迪法术。",
    [3509] = "与艾萨拉的亚考罗克谈一谈。你应该在海边搜索亚考兰神殿。",
    [3510] = "杀掉赫塔拉，将染血的赫塔拉头颅、破碎的赫塔拉头颅和淤血的赫塔拉头颅交给亚考罗克。",
    [3511] = "将调剂交给洛拉姆斯·萨里比迪斯。",
    [3520] = "在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。",
    [3527] = "将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。",
    [3528] = "将装满的哈卡之卵交给塔纳利斯的叶基亚。",
    [3602] = "在艾萨拉南部收集20块艾萨拉晶体。你可以使用地狱犬协助寻找一些隐藏的矿脉。$B$B任务完成之后就回到洛拉姆斯那里去。",
    [3621] = "把货物交给荆棘谷的加尔文。",
    [3625] = "等待加尔文为你锻造武器。",
    [3626] = "回到部落英雄的灵魂那里。",
    [3627] = "杀掉毁灭者戈洛尔、瑟温妮，以及大法师奥利斯塔。从他们到尸体上拿到戈洛尔的护符、瑟温妮的护符和奥利斯塔的护符。$B$B记住使用你的魔化艾萨拉水晶武器来削弱他们，否则他们是无法被杀死的——你必须小心谨慎地使用你的武器……",
    [3628] = "消灭污染者拉瑟莱克，将污染者之角交给部落英雄的灵魂。另外你还要把污染者防护结界交给他，这样部落英雄的灵魂就可以消灭它，以避免它落入邪恶势力之手。",
    [3631] = "与贫瘠之地棘齿城的斯坦哈德·法尔杉谈一谈。",
    [3701] = "到燃烧平原的索瑞森废墟中去，从索瑞森遗物上搜集信息。当你收集到足够的信息之后，就回到皇家历史学家阿克瑟努斯那里。",
    [3702] = "听皇家历史学家阿克瑟努斯讲述索瑞森的历史。",
    [3783] = "为永望镇的乌米收集10张厚雪人毛皮。",
    [3801] = "如果你想要得到进入这座城市主城区的钥匙，就去和弗兰克罗恩·铸铁谈一谈。",
    [3802] = "杀掉弗诺斯·达克维尔并拿回战锤铁胆。把铁胆之锤拿到索瑞森神殿去，将其放在弗兰克罗恩·铸铁的雕像上。",
    [3844] = "在池塘附近查找与搁浅的小艇有关的线索。",
    [3845] = "查看袋子里的东西，然后将它们交给物主。",
    [3903] = "与米莉·奥斯沃斯谈一谈。",
    [3904] = "收集8箱米莉的葡萄，把它们交给北郡修道院的米莉·奥斯沃斯。",
    [3907] = "进入黑石深渊并找到伊森迪奥斯。杀掉它，然后把你找到的信息汇报给桑德哈特。",
    [3908] = "把林克的剑交给冬泉谷的多诺瓦·雪山。",
    [3909] = "去菲拉斯找格雷甘·山酒。从他那里问到获取视灵药剂的方法，然后向冬泉谷的多诺瓦·雪山复命。",
    [3912] = "在加基森镇外的墓地中使用视灵药剂，然后按照多诺瓦的指示找到加里杨。",
    [3913] = "复活，然后寻找加里杨让你去找的那块墓碑。",
    [3914] = "把林克的强化之剑交给安戈洛尔环形山的林克。",
    [3941] = "到马绍尔营地那里的山洞中去找科琳。",
    [3942] = "到费伍德森林去找艾瑞丹·蓝风。",
    [3961] = "把亚奎门塔斯的银图腾交给马绍尔营地里的林克。",
    [3962] = "到马绍尔营地南边的火羽山去。$B$B找到火焰使者，并使用图腾除掉它的防护光环。在击败它之后从洞中取得金色火焰。",
    [3981] = "在黑石深渊里找到指挥官哥沙克。$B$B在那幅草图上画着的是一个铁栏后面的兽人，也许你应该到某个类似监狱的地方去找找看。",
    [3982] = "保护哥沙克。",
    [4001] = "与卡兰·巨锤谈一谈，收集关于绑架公主铁炉堡公主茉艾拉·铜须这一事件的情报。将情报反馈给奥格瑞玛城里的萨尔。$B$B哥沙克提到过卡兰被关在附近的某个牢房中。",
    [4002] = "如果你准备好要接受萨尔所安排的任务，就去找他谈一谈。",
    [4003] = "杀掉达格兰·索瑞森大帝，然后将铁炉堡公主茉艾拉·铜须从他的邪恶诅咒中拯救出来。",
    [4004] = "向萨尔报告！",
    [4005] = "把阿奎尔之书、银爪和铁树之心带到塔纳利斯去。$B$B使用这本书召唤亚奎门塔斯。$B$B在图腾完成之后，把它交给马绍尔营地的科琳。",
    [4024] = "到黑石深渊去杀掉贝尔加。$B$B你只知道这个巨型怪物住在黑石深渊的最深处。记住你要使用特殊的黑龙皮从贝尔加的尸体上采集烈焰精华。$B$B将你采集到的烈焰精华交给塞勒斯·萨雷芬图斯。",
    [4063] = "找到并杀掉傀儡统帅阿格曼奇，将他的头交给鲁特维尔。你还需要从守卫着阿格曼奇的狂怒傀儡和战斗傀儡身上收集10块完整的元素核心。",
    [4081] = "到黑石深渊去消灭那些邪恶的侵略者！$B$B军官高图斯要你去杀死15个铁怒卫士、10个铁怒狱卒和5个铁怒步兵。完成任务之后回去向他复命。",
    [4082] = "到黑石深渊去消灭那些邪恶的侵略者！$B$B高图斯军阀要你杀死10个铁怒医师,、10个铁怒士兵和10个铁怒军官。完成任务之后回去向他复命。",
    [4083] = "Requirements:$B- 星光红宝石 x 2$B- 金锭 x 20$B- 真银锭 x 10",
    [4084] = "为费伍德森林的艾瑞丹·蓝风收集11只银爪和1颗铁树之心。",
    [4121] = "押送你的囚犯格拉克·洛克鲁布。穿过燃烧平原和黑石山脉，一直走到灼热峡谷。$B$B雷克斯洛特曾经告诉过你，他会让他的人等在黑石山脉的另外一边准备接收格拉克。$B$B另外，你还要把瑟银镣铐一并还给雷克斯洛特。",
    [4122] = "到燃烧平原去找到格拉克·洛克鲁布。你回忆起雷克斯洛特曾经提起过，格拉克应该是在一座大型的黑石要塞中。$B$B当你找到格拉克·洛克鲁布之后，用瑟银镣铐把他铐起来，然后将其带回灼热峡谷。雷克斯洛特会让他的部下等在那里接应你。",
    [4123] = "把山脉之心交给燃烧平原的麦克斯沃特·尤博格林。",
    [4124] = "和羽月要塞的基恩诺·火花谈一谈。",
    [4125] = "找到信使的小船，你应该在菲拉斯的南部海岸线上展开搜索。",
    [4126] = "把遗失的雷酒秘方带给卡拉诺斯的拉格纳·雷酒。",
    [4127] = "回到羽月要塞，给基恩诺·火花看看你找到的这把被丢弃的小刀。",
    [4128] = "和拉格纳·雷酒谈一谈。",
    [4129] = "把被丢弃的小刀交给羽月要塞的奎恩提斯。",
    [4130] = "和羽月要塞的基恩诺·火花谈一谈。",
    [4131] = "在菲拉斯南部地区的木爪豺狼人营地里寻找信使的下落或者信使的物品。",
    [4132] = "到黑石深渊去杀掉安格弗将军！当任务完成之后向军官高图斯复命。",
    [4133] = "与卡加斯的暗法师薇薇安·拉格雷谈一谈。",
    [4134] = "把遗失的雷酒秘方交给卡加斯的薇薇安·拉格雷。",
    [4135] = "现在你已经知道了拉斯卡尔的去向，那么你最好到痛苦深渊去寻找他，或者至少是他的尸体。根据便笺上的信息，那个地方应该在木爪豺狼人营地的南边。",
    [4136] = "把雷布里的头颅交给燃烧平原的尤卡·斯库比格特。",
    [4182] = "杀掉15条黑色小龙、10条黑色龙兽和1条黑色幼龙。当你完成任务之后就向赫林迪斯·河角回报。",
    [4183] = "把赫林迪斯·河角的信交给湖畔镇的所罗门镇长。",
    [4184] = "到暴风城去把所罗门的求援信交给伯瓦尔·弗塔根公爵。$B$B伯瓦尔在暴风要塞里。",
    [4185] = "与女伯爵卡特拉娜·普瑞斯托谈话，然后再与伯瓦尔·弗塔根公爵谈话。",
    [4186] = "把伯瓦尔的命令交给湖畔镇的所罗门镇长。",
    [4201] = "将4份格罗姆之血、10块巨型银矿和装满水的娜玛拉之瓶交给黑石深渊的娜玛拉小姐。",
    [4223] = "和燃烧平原的麦克斯韦尔元帅谈一谈。",
    [4224] = "和狼狈不堪的约翰谈谈来了解温德索尔元帅的命运，然后回到麦克斯韦尔元帅那里。$B$B你想起麦克斯韦尔元帅说过他在一个北面的洞穴那里。",
    [4241] = "到西北部的黑石山脉去，在黑石深渊中找到温德索尔元帅的下落。$B$B狼狈不堪的约翰曾告诉你说温德索尔被关进了一个监狱。",
    [4242] = "把这个坏消息传达给麦克斯韦尔元帅。",
    [4263] = "在黑石深渊里找到伊森迪奥斯，然后把他干掉！",
    [4264] = "温德索尔元帅也许会对你手中的东西感兴趣。毕竟，希望还没有被完全扼杀。",
    [4265] = "将拉斯卡尔安全护送到祖卡什虫巢外。$B$B回到羽月要塞的基恩诺·火花那儿，告诉他拉斯卡尔还活着，且状况良好。",
    [4266] = "与羽月要塞的珊蒂斯·羽月谈一谈。",
    [4267] = "把拉斯卡尔的报告交给达纳苏斯的格拉希娜·灵风。",
    [4281] = "将未递送的包裹交给萨兰纳尔驿站的法芬德尔。",
    [4282] = "找回温德索尔元帅遗失的情报。$B$B温德索尔元帅确信那些情报在安格弗将军和傀儡统帅阿格曼奇的手里。",
    [4286] = "到黑石深渊去找到20个黑铁挎包。当你完成任务之后，回到奥拉留斯那里复命。你认为黑石深渊里的黑铁矮人应该会有这些黑铁挎包。",
    [4322] = "帮助温德索尔元帅拿回他的装备并救出他的朋友。当你成功之后就回去向麦克斯韦尔元帅复命。",
    [4324] = "与燃烧平原的尤卡·斯库比格特谈一谈。",
    [4341] = "去黑石深渊找到卡兰·巨锤。$B$B国王提到卡兰在那里负责看守囚犯——也许你应该在监狱附近寻找他。",
    [4342] = "听卡兰·巨锤说他的故事。",
    [4361] = "回到铁炉堡，把这个坏消息带给国王麦格尼·铜须。",
    [4362] = "回到黑石深渊，从达格兰·索瑞森大帝的魔掌中救出铁炉堡公主茉艾拉·铜须。",
    [4363] = "回到铁炉堡去，与国王麦格尼·铜须谈一谈。",
    [4487] = "与棘齿城的斯坦哈德·法尔杉谈一谈。",
    [4488] = "与棘齿城的斯坦哈德·法尔杉谈一谈。",
    [4489] = "与棘齿城的斯坦哈德·法尔杉谈一谈。",
    [4490] = "与棘齿城的斯坦哈德·法尔杉谈一谈，学习召唤地狱战马的能力。",
    [4701] = "到黑石塔去摧毁那里的座狼源头。当你离开的时候，赫林迪斯喊出了一个名字：哈雷肯。这个词就是兽人语中“座狼”的意思。",
    [4724] = "杀死血斧座狼的领袖，哈雷肯。",
    [4729] = "到黑石塔去找到血斧座狼幼崽。使用笼子来捕捉这些凶猛的小野兽，然后把笼中的座狼幼崽交给基布雷尔。",
    [4734] = "在孵化间对着某颗龙蛋使用龙蛋冷冻器初号机。",
    [4735] = "将电动采集模块和8颗收集到的龙蛋交给燃烧平原烈焰峰的丁奇·斯迪波尔。",
    [4742] = "找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。$B$B可能携带者三块宝石的将军是：燃棘氏族的指挥官沃恩、尖石氏族的欧莫克大王，以及血斧氏族的维姆萨拉克。",
    [4743] = "到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。$B$B此时，你必须尽快将未铸造的晋升印章放在这条龙面前，并使用龙力宝珠控制他的躯体，强迫他将黑龙的烈焰喷向未铸造的晋升印章！",
    [4764] = "将末日扣环交给燃烧平原的玛亚拉·布莱特文。",
    [4765] = "将瑞治维尔的箱子交给暴风城的雷明顿·瑞治维尔。",
    [4766] = "与燃烧平原的玛亚拉·布莱特文谈一谈。",
    [4768] = "将黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。",
    [4769] = "与卡加斯的暗法师薇薇安·拉格雷谈一谈。",
    [4771] = "将黎明先锋放在通灵学院的观察室里。打败维克图斯，然后回到贝蒂娜·比格辛克那里去。",
    [4787] = "将远古之卵交给塔纳利斯的叶基亚。",
    [4788] = "将第五块和第六块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。",
    [4862] = "到黑石塔去为基布雷尔收集15枚尖塔蜘蛛卵。$B$B听说那些蜘蛛周围有许多这样的卵。",
    [4866] = "你可以在黑石塔的中心地带找到烟网蛛后。与她战斗，让她在你体内注入毒汁。如果你有能力的话，就杀死她吧。当你中毒之后，回到狼狈不堪的约翰那儿，他会从你的身体里抽取这些“蛛后的乳汁”。",
    [4867] = "阅读瓦罗什的卷轴。将瓦罗什的蟑螂交给他。",
    [4903] = "杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。",
    [4907] = "与丁奇·斯迪波尔谈一谈。",
    [4921] = "找到曼科里克的妻子，然后回到十字路口找他。",
    [4941] = "和奥格瑞玛的伊崔格谈一谈。讨论完毕后，咨询萨尔的意见。$B$B你回忆起曾在萨尔的大厅中见过伊崔格。",
    [4974] = "去黑石塔杀死大酋长雷德·黑手，带着他的头颅返回奥格瑞玛。",
    [4981] = "到黑石塔去查明比修的下落。",
    [4982] = "找到比修的装置并把它们还给她。你记得她说过她把装置藏在城市的最底层。",
    [4983] = "把比修的侦查报告交给卡加斯的雷克斯洛特。",
    [5001] = "找到比修的装置并把它们还给她。祝你好运！",
    [5002] = "到燃烧平原去，把比修的情报交给麦克斯韦尔元帅。",
    [5047] = "与永望镇的玛雷弗斯·暗锤谈一谈。",
    [5061] = "回到达纳苏斯，让玛斯雷·驭熊者看看你的海狮坠饰。",
    [5065] = "把第三块和第四块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。",
    [5081] = "到黑石塔去消灭指挥官沃恩、欧莫克大王和维姆萨拉克。完成任务之后回到麦克斯韦尔元帅处复命。",
    [5089] = "把达基萨斯将军的命令交给燃烧平原的麦克斯韦尔元帅。",
    [5096] = "到血色十字军建在费尔斯通农场和达尔松之泪之间的营地去，摧毁他们的指挥帐篷。$B$B将亡灵天灾的战旗插在营地中，然后回到西瘟疫之地亡灵壁垒的高级执行官德灵顿那儿。",
    [5097] = "使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。$B$B在做完了标记之后，将信号火炬还给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。",
    [5098] = "使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。$B$B在做完了标记之后，将信号火炬还给西瘟疫之地亡灵壁垒的高级执行官德灵顿。",
    [5102] = "到黑石塔去杀掉达基萨斯将军，完成任务之后就回到麦克斯韦尔元帅那里复命。",
    [5122] = "Requirements:$B- 信仰奖章",
    [5125] = "$N，我快要死了……但我的灵魂得救了。为此，我欠你的远非言语所能表达。请收下这个……继续战斗吧，勇敢的$C！",
    [5127] = "到黑石塔去找到古拉鲁克。杀死他，然后用血污长矛刺入他的尸体。当他的灵魂被吸干后，这支矛就会成为穿魂长矛。$B$B你还必须找到未铸造的符文覆饰胸甲。$B$B将穿魂长矛和未铸造的符文覆饰胸甲都交给冬泉谷的罗拉克斯。",
    [5142] = "找到帕米拉·雷德帕斯。",
    [5149] = "找到帕米拉的洋娃娃。",
    [5152] = "与安多哈尔废墟南边的玛莱恩谈一谈。",
    [5153] = "把约瑟夫的结婚戒指交给安多哈尔的克罗米。",
    [5154] = "把《达隆郡的历史》交给安多哈尔的克罗米。",
    [5160] = "到冬泉谷去找到哈尔琳，把奥比的鳞片交给她。",
    [5163] = "带着乌米的机械雪人去吓唬她的朋友：$B$B永望镇的莱加奇（冬泉谷）、加基森的斯普琳科（塔纳利斯），还有马绍尔营地的奎克希尔（安戈洛环形山）。$B$B当你完成任务之后，把机械雪人还给乌米。",
    [5168] = "把达维的圣契和雷德帕斯之盾交给卡林·雷德帕斯。",
    [5181] = "将霍古斯的颅骨和马杜克的破碎之剑交给圣光之愿礼拜堂的卡林·雷德帕斯。",
    [5206] = "把5个共鸣颅骨和神秘水晶交给东瘟疫之地的卡林·雷德帕斯。",
    [5210] = "将《达隆镇全史》交给东瘟疫之地的卡林·雷德帕斯。",
    [5211] = "释放15个达隆郡居民的灵魂，然后返回卡林·雷德帕斯身边。",
    [5212] = "从斯坦索姆找回20个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……",
    [5213] = "到斯坦索姆去探索那里的通灵塔。找到新的天灾军团档案，把它交给贝蒂娜·比格辛克。",
    [5214] = "找到艾兹拉·格里姆在斯坦索姆的烟草店，并从中找回一盒格里姆的优质香烟，把它交给烟鬼拉鲁恩。",
    [5241] = "找到卡林·瑞德巴思。",
    [5243] = "到北方的斯坦索姆去，寻找散落在城市中的补给箱，并收集5瓶斯坦索姆圣水。当你找到足够的圣水之后就回去向莱尼德·巴萨罗梅复命。",
    [5251] = "在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。",
    [5262] = "将巴纳扎尔的头颅交给东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。",
    [5263] = "到斯坦索姆去杀掉瑞文戴尔男爵，把他的头颅交给尼古拉斯·瑟伦霍夫公爵。",
    [5282] = "对斯坦索姆城中的鬼魂使用埃根的冲击器。当那些永不安息的灵魂挣脱他们的外壳时，再次使用埃根的冲击器——他们就可以获得自由了！$B$B解放15个永不安息的灵魂，然后回到埃根那里去。",
    [5341] = "到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到阿莱克斯·巴罗夫那儿去。",
    [5342] = "到冰风岗——联盟的领地——去暗杀维尔顿·巴罗夫。把他的脑袋交给阿莱克斯·巴罗夫。$B$B要多加小心，联盟也许对维尔顿实施了严密的保护。",
    [5343] = "到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到维尔顿·巴罗夫那儿去。",
    [5344] = "去亡灵壁垒——部落的领地——去暗杀阿莱克斯·巴罗夫。把他的脑袋交给维尔顿·巴罗夫。$B$B要小心，部落也许对阿莱克斯实施了严密的保护。",
    [5382] = "在通灵学院中找到瑟尔林·卡斯迪诺夫教授。杀死他，并烧毁艾瓦·萨克霍夫和卢森·萨克霍夫的遗体。任务完成后就回到艾瓦·萨克霍夫那儿。",
    [5383] = "将恐惧之袋交给凯尔达隆的艾瓦·萨克霍夫。",
    [5384] = "带着无辜者之血回到通灵学院，将它放在门廊的火盆下面，基尔图诺斯会前来吞噬你的灵魂。$B$B勇敢地战斗吧，不要退缩！杀死基尔图诺斯，然后回到艾瓦·萨克霍夫那儿。",
    [5461] = "到阿拉希高地的激流堡遗迹里面寻找巫妖生前的遗物。如果你能找到这样的东西，就把它交给马杜克镇长。",
    [5462] = "到东瘟疫之地的圣光之愿礼拜堂去找到莱尼德·巴萨罗梅，给他看看巫妖生前的遗物，并告诉他你收集到的情报。",
    [5463] = "到斯坦索姆城里去找到米奈希尔的礼物，把巫妖生前的遗物放在那块邪恶的土地上。",
    [5464] = "把禁锢灵魂的遗物交给东瘟疫之地的莱尼德·巴萨罗梅。",
    [5465] = "回到凯尔达隆的马杜克镇长那里，把禁锢灵魂的遗物交给他。",
    [5466] = "在通灵学院里找到莱斯·霜语。当你找到他之后，使用禁锢灵魂的遗物破除其亡灵的外壳。如果你成功地破除了他的不死之身，就杀掉他并拿到莱斯·霜语的头颅。把那个头颅交给马杜克镇长。",
    [5514] = "把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。",
    [5515] = "在通灵学院找到詹迪斯·巴罗夫并打败她。从她的尸体上找到卡斯迪诺夫的恐惧之袋，然后将其交给艾瓦·萨克霍夫。",
    [5518] = "把4份符文布卷、8块硬甲皮、2卷符文线和一份食人魔鞣酸交给诺特·希姆加克。他现在被拴在厄运之槌的戈多克食人魔那边。",
    [5525] = "Requirements:$B- 戈多克镣铐钥匙",
    [5528] = "你是头儿，可以喝我的酒！让你精神焕发！都是好酒，头儿……你尝尝，告诉克雷格！",
    [5529] = "杀掉20只瘟疫龙崽，然后向圣光之愿礼拜堂的贝蒂娜·比格辛克复命。",
    [5531] = "将冰冻的龙蛋交给贝蒂娜·比格辛克。",
    [5533] = "和西瘟疫之地冰风岗的化学家阿尔比顿谈一谈。",
    [5537] = "将15块骷髅碎片交给西瘟疫之地冰风岗的化学家阿尔比顿。",
    [5538] = "把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。",
    [5582] = "把健康的龙鳞交给东瘟疫之地圣光之愿礼拜堂中的贝蒂娜·比格辛克。",
    [5601] = "在达隆郡里找到帕米拉·雷德帕斯。",
    [5721] = "将遗物包裹放在达隆郡的广场中。$B$B在霍古斯死亡之前，达维必须存活。$B$B在雷德帕斯队长堕落之前保证他存活。$B$B击败堕落的雷德帕斯。$B$B当约瑟夫·雷德帕斯出现在广场中时，与他的灵魂进行交谈，然后回到帕米拉的家中去找帕米拉。",
    [5742] = "听听提里奥·弗丁要说什么。",
    [5762] = "将克拉维尔的箱子送到荆棘谷的赫米特·奈辛瓦里那里。",
    [5763] = "将鲁恩的科多兽角送到荆棘谷的赫米特·奈辛瓦里那里。",
    [5781] = "到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。",
    [5801] = "把骷髅钥匙模具和2块瑟银锭带到安戈洛尔环形山地区的火羽山顶部。在熔岩湖旁使用骷髅钥匙模具，铸造出一把未完工的骷髅钥匙。$B$B把未完工的骷髅钥匙交给西瘟疫之地冰风岗的化学家阿尔比顿。",
    [5802] = "把骷髅钥匙模具和2块瑟银锭带到安戈洛尔环形山地区的火羽山顶部。在熔岩湖旁使用骷髅钥匙模具，铸造出一把未完工的骷髅钥匙。$B$B把未完工的骷髅钥匙交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。",
    [5803] = "杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地冰风岗的化学家阿尔比顿。",
    [5804] = "杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。",
    [5845] = "到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。",
    [5846] = "到凯尔达隆岛去，寻找关于那副画的线索。凯尔达隆岛在瘟疫之地南部的湖中央。",
    [5848] = "到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到“爱与家庭”这幅画，它被隐藏在另一幅描绘两个月亮的画之后。$B$B把这幅画还给提里奥·弗丁。",
    [5861] = "到瘟疫之地南部的乌瑟尔之墓去，将提里奥的礼物交给巫女麦兰达。",
    [5862] = "和巫女麦兰达交谈以获得血色幻象的效果。在血色幻象的掩护下深入壁炉谷，将提里奥的礼物交给大领主泰兰·弗丁。$B$B壁炉谷在北方，泰兰应该在玛登霍尔德城堡里面。",
    [5921] = "使用法术“传送：月光林地”抵达月光林地，在那里与永夜港的德迪利特·星焰谈一谈。",
    [5922] = "使用法术“传送：月光林地”抵达月光林地，在那里与永夜港的德迪利特·星焰谈一谈。",
    [5923] = "与达纳苏斯塞纳里奥区的玛斯雷·驭熊者谈一谈。",
    [5924] = "与达纳苏斯塞纳里奥区的玛斯雷·驭熊者谈一谈。",
    [5925] = "与达纳苏斯塞纳里奥区的玛斯雷·驭熊者谈一谈。",
    [5926] = "与雷霆崖长者高地上的图拉克·符文图腾谈一谈。",
    [5927] = "与雷霆崖长者高地上的图拉克·符文图腾谈一谈。",
    [5928] = "与雷霆崖长者高地上的图拉克·符文图腾谈一谈。",
    [5929] = "到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。",
    [5930] = "到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。",
    [5931] = "回到达纳苏斯，与塞纳里奥区的玛斯雷·驭熊者谈一谈。",
    [5932] = "回到雷霆崖，与长者高地的图拉克·符文图腾谈一谈。",
    [5941] = "将一包遗物交给安多哈尔的克罗米。",
    [5942] = "用约瑟夫的钥匙打开约瑟夫的箱子。",
    [5944] = "护送泰兰·弗丁走出壁炉谷。",
    [6001] = "使用奥伯丁的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。$B$B任务完成之后，与达纳苏斯的玛斯雷·驭熊者谈一谈。",
    [6002] = "使用莫高雷与贫瘠之地交界处的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。$B$B任务完成之后，与雷霆崖的图拉克·符文图腾谈一谈。",
    [6004] = "杀死2个血色医护员、2个血色猎人、2个血色魔法师和2个血色骑士，然后回到西瘟疫之地的科尔斯塔·迪普沙东那儿。",
    [6023] = "杀掉猎人莱德雷和骑士杜尔根，然后向西瘟疫之地的科尔斯塔·迪普沙东复命。",
    [6025] = "进入壁炉谷并找一处高地，你可以在那里观察整个城镇并估算血色十字军的兵力，然后向西瘟疫之地的科尔斯塔·迪普沙东回报。",
    [6061] = "使用驯兽棒驯服成年陆行鸟。练习你的技能，然后将驯兽棒还给血蹄村的雅文·刺鬃。",
    [6062] = "使用驯兽棒驯服可怕的杂斑野猪。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。",
    [6063] = "使用驯兽棒驯服树林潜伏者。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。",
    [6064] = "使用驯兽棒驯服大型峭壁野猪。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。",
    [6065] = "与血蹄村的雅文·刺鬃谈一谈。",
    [6066] = "与血蹄村的雅文·刺鬃谈一谈。",
    [6067] = "与血蹄村的雅文·刺鬃谈一谈。",
    [6068] = "与剃刀岭的索塔尔谈一谈。",
    [6069] = "与剃刀岭的索塔尔谈一谈。",
    [6070] = "与剃刀岭的索塔尔谈一谈。",
    [6071] = "与多兰纳尔的达扎拉谈一谈。",
    [6072] = "与多兰纳尔的达扎拉谈一谈。",
    [6073] = "与多兰纳尔的达扎拉谈一谈。",
    [6074] = "与卡拉诺斯的格瑞夫谈一谈。",
    [6075] = "与卡拉诺斯的格瑞夫谈一谈。",
    [6076] = "与卡拉诺斯的格瑞夫谈一谈。",
    [6081] = "与奥格瑞玛的奥玛克谈一谈。",
    [6082] = "使用驯兽棒驯服硬甲蝎。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。",
    [6083] = "使用驯兽棒驯服海浪蟹。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。",
    [6084] = "使用驯兽棒驯服雪豹。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。",
    [6085] = "使用驯服兽棒驯服一头冰爪熊。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。",
    [6086] = "与铁炉堡的贝莉亚·雷岩谈一谈。",
    [6087] = "使用驯兽棒驯服一只草原捕食者。练习你的技能，然后将驯兽棒还给血蹄村的雅文·刺鬃。",
    [6088] = "使用驯兽棒驯服一只猛鹫。练习你的技能，然后将驯服法杖交还给血蹄村的雅文·刺鬃。",
    [6089] = "与雷霆崖猎人高地的浩特·雷角谈一谈。",
    [6101] = "使用驯兽棒驯服一只夜刃捕食者。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。",
    [6102] = "使用驯兽棒驯服一只巨翼恶枭。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。",
    [6103] = "与达纳苏斯塞纳里奥区的祖卡斯特谈一谈。",
    [6121] = "到月光林地去，与永夜港的德迪利特·星焰谈一谈。",
    [6122] = "使用空的峭壁之泉取样器在瀑布洞口获得水样。$B$B将盛满的峭壁之泉取样器送到黑海岸奥伯丁的奥兰达利亚·夜歌那里。",
    [6123] = "收集5个地根草和12个月亮菇，把它们交给奥伯丁的奥兰达利亚·夜歌，这样她就可以制作解药了。",
    [6124] = "对黑海岸的10头生病的鹿使用动物医疗药膏，以此来治疗它们。从壁泉河到奥伯丁，直到最南端靠近灰谷的地区都有生病的鹿出没。",
    [6125] = "回到达纳苏斯塞纳里奥区的玛斯雷·驭熊者那里。",
    [6126] = "到月光林地去，与永夜港的德迪利特·星焰谈一谈。",
    [6127] = "使用空的鬼雾峰取样器在山顶取水样。$B$B将盛满的鬼雾峰取样器送到贫瘠之地十字路口的图加·符文图腾那里。",
    [6128] = "收集5个地根草和5个科多兽角，把它们交给十字路口的图加·符文图腾，这样他就可以制作解药了。",
    [6129] = "对贫瘠之地北部的10只生病的瞪羚使用动物医疗药膏，以此来治疗它们。在穿过十字路口的那条东西走向的大路北面到处都是生病的蹬羚。",
    [6130] = "回到雷霆崖长者高地的图拉克·符文图腾那里。",
    [6141] = "与凄凉之地的安东修士谈一谈。",
    [6144] = "到幽暗城去与瓦里玛萨斯谈一谈。",
    [6145] = "返回东瘟疫之地，找到并杀死红衣信使，拿到大十字军的命令。$B$B把命令交给纳萨诺斯·凋零者，并等待进一步的指示。",
    [6146] = "到玛瑞斯农场东南方的提尔之手去，抵达那里之后就咬一口烂苹果。在血色十字军伪装的掩护下，把大十字军的命令交给十字军领主瓦德玛尔。",
    [6147] = "带着新情报返回纳萨诺斯·凋零者那里。",
    [6148] = "血色十字军正在从提尔之手到斯坦索姆的路上巡逻，你可以在巡逻队中找到圣者德米提雅和她的随从，找到并杀死她。如果你成功了，就回到纳萨诺斯·凋零者那里去复命。",
    [6163] = "到斯坦索姆去，杀掉吞咽者拉姆斯登。把他的头颅交给纳萨诺斯。",
    [6402] = "前往暴风城的城门。与侍卫洛文交谈，他会通知温德索尔元帅你已经到达了。",
    [6403] = "跟随雷吉纳德·温德索尔元帅在暴风城中前进。保护他，别让他受到伤害！",
    [6501] = "你必须寻遍世界以找到一种能恢复龙眼碎片的能量的生物。你对这种生物的唯一了解就是：他们确实存在。",
    [6502] = "你必须从达基萨斯将军手中取得黑龙勇士之血。",
    [6566] = "听萨尔讲话。",
    [6567] = "按照酋长的指示找到雷克萨。他在石爪山和菲拉斯之间的凄凉之地游荡。",
    [6568] = "把雷克萨的证明交给西瘟疫之地的巫女麦兰达。",
    [6569] = "到黑石塔去收集20颗黑色龙兽的眼球，完成任务之后回到巫女麦兰达那里。",
    [6570] = "到尘泥沼泽中的巨龙沼泽去，找到埃博斯塔夫的洞穴。进入洞穴之后戴上龙形护符，然后跟埃博斯塔夫交谈。",
    [6582] = "找到蓝龙斯克利尔并杀掉他。从他的身上取下他的颅骨，然后将其交给埃博斯塔夫。$B$B你可以在冬泉谷找到斯克利尔。",
    [6583] = "杀掉绿龙索姆努斯，把他的颅骨交给埃博斯塔夫。",
    [6584] = "诺兹多姆的孩子克鲁纳里斯在塔纳利斯沙漠守卫着时光之穴。杀了他，把他的颅骨交给埃博斯塔夫。",
    [6585] = "到格瑞姆巴托去杀掉红龙埃克托兹，把他的颅骨交给埃博斯塔夫。",
    [6601] = "看来这场假面舞会就要结束了。你知道麦兰达为你制作的龙形护符在黑石塔里面不会发挥作用，也许你应该去找雷克萨，将你的困境告诉他。把黯淡的龙火护符给他看看，也许他知道下一步该怎么做。",
    [6602] = "到黑石塔去杀掉达基萨斯将军，把它的血交给雷克萨。",
    [6681] = "把拉文霍德徽记交给拉文霍德庄园的法拉德，庄园就坐落在希尔斯布莱德的群山之中。$B$B你的智慧将在这次旅途中得到考验。做好准备吧。",
    [6721] = "与多兰纳尔的达扎拉谈一谈。",
    [6722] = "与多兰纳尔的达扎拉谈一谈。",
    [6981] = "寻找更多有关这块噩梦碎片的信息。",
    [7028] = "为凄凉之地的维洛收集25个瑟莱德丝水晶雕像。",
    [7029] = "在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。$B$B在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。$B$B治疗8株植物并杀死那些诺克赛恩幼体，然后向葬影村的瓦克·战痕复命。",
    [7041] = "在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。$B$B在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。$B$B治疗8株植物并杀死那些诺克赛恩幼体，然后向尼耶尔前哨站的塔琳德莉亚复命。",
    [7044] = "找回塞雷布拉斯节杖的两个部分：塞雷布拉斯魔棒和塞雷布拉斯钻石。$B$B然后设法和塞雷布拉斯对话。",
    [7046] = "帮助赎罪的塞雷布拉斯制作塞雷布拉斯节杖。$B$B当仪式完成之后再和他谈谈。",
    [7064] = "杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。",
    [7065] = "杀死瑟莱德丝公主，然后回到凄凉之地尼耶尔前哨站的守护者玛兰迪斯那里复命。",
    [7066] = "到月光林地去找到雷姆洛斯，将生命之种交给他。",
    [7067] = "阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。",
    [7068] = "从玛拉顿收集10块暗影残片，然后把它们交给奥格瑞玛的尤塞尔奈。",
    [7070] = "从玛拉顿收集10块暗影残片，然后把它们交给尘泥沼泽塞拉摩岛上的大法师特沃什。",
    [7201] = "前往黑石深渊，找回10份元素精华。你首先想到的是搜查魔像和魔像制造者。你还记得薇薇安·拉格雷含糊地提到过元素生物。",
    [7441] = "到厄运之槌去找到小鬼普希林。你可以使用任何手段从小鬼那里得到埃斯托尔迪的咒术之书。$B$B找到咒术之书后，回到拉瑞斯小亭的埃斯托尔迪那里。",
    [7461] = "你必须干掉5座水晶塔周围的守卫，那5座水晶塔维持着关押伊莫塔尔的监狱。一旦水晶塔的能量被削弱，伊莫塔尔周围的能量力场就会消散。$B$B进入伊莫塔尔的监狱，干掉站在中间的那个恶魔。最后，在图书馆挑战托塞德林王子。$B$B当任务完成之后，到庭院中去找辛德拉古灵。",
    [7462] = "返回图书馆去找到辛德拉的宝藏。拿取你的奖励吧！",
    [7463] = "到厄运之槌的扭木广场去杀掉水元素海多斯博恩。把海多斯博恩精华交给图书馆的博学者莱德罗斯。",
    [7481] = "到厄运之槌去寻找泰尔米乌斯·探梦者。向莫沙彻营地的先知科鲁拉克报告你所找到的信息。",
    [7482] = "到厄运之槌去寻找泰尔米乌斯·探梦者。向羽月要塞的学者卢索恩·纹角报告你所找到的信息。",
    [7488] = "把蕾瑟塔蒂丝的网交给菲拉斯羽月要塞的拉托尼库斯·月矛。",
    [7489] = "把蕾瑟塔蒂丝的网交给非拉斯莫沙彻营地的塔罗·刺蹄。",
    [7490] = "将奥妮克希亚的头颅交给奥格瑞玛的萨尔。",
    [7491] = "在力量谷找到伦萨克。",
    [7492] = "和菲拉斯莫沙彻营地的塔罗·刺蹄谈一谈。",
    [7493] = "屠龙者，还是一位经验丰富的制皮师？你总是让我惊叹不已，英雄。我自愧不如。$B$B请接受我即将传授给你的知识。如果你要消灭黑龙军团的残余势力，这些知识将会无比宝贵。$B$B用龙母的鳞片制作这件斗篷吧。它能保护你和你的盟友，抵御黑石领主……奈法利安那炽热的吐息。",
    [7494] = "和菲拉斯羽月要塞的拉托尼库斯·月矛谈一谈。",
    [7495] = "将奥妮克希亚的头颅交给暴风城的伯瓦尔·弗塔根公爵。",
    [7496] = "在英雄谷找到玛丁雷少校。",
    [7497] = "屠龙者，还是一位经验丰富的制皮师？你总是让我惊叹不已，英雄。我自愧不如。$B$B请接受我即将传授给你的知识。如果你要消灭黑龙军团的残余势力，这些知识将会无比宝贵。$B$B用龙母的鳞片制作这件斗篷吧。它能保护你和你的盟友，抵御黑石领主……奈法利安那炽热的吐息。",
    [7498] = "将这本典籍交给它的主人。",
    [7499] = "将这本典籍交给它的主人。",
    [7500] = "将这本典籍交给它的主人。",
    [7501] = "将这本典籍交给它的主人。",
    [7502] = "将这本典籍交给它的主人。",
    [7503] = "将这本典籍交给它的主人。",
    [7504] = "将这本典籍交给它的主人。",
    [7505] = "将这本典籍交给它的主人。",
    [7506] = "将这本典籍交给它的主人。",
    [7507] = "将《诺斯特罗的屠龙技术纲要》还回图书馆。",
    [7508] = "把黯淡的精灵剑交给博学者莱德罗斯。",
    [7509] = "你必须设法让奥妮克希亚对这把未淬火的的上古之刃喷射火焰。完成之后，捡起加热过的上古之刃。你要注意的是，加热过的上古之刃不会一直保持被加热的状态，时间非常紧迫。$B$B在把它给我拿回来之前的最后一步是杀掉那条龙，并将加热过的上古之刃插入她的尸体中。$B$B完成这些之后，奎尔塞拉就是你的了。",
    [7562] = "与燃烧平原的莫苏尔·召血者谈一谈。",
    [7563] = "把30瓶狂暴野兽的血交给燃烧平原的莫苏尔·召血者。",
    [7564] = "把血箱交给燃烧平原的戈瑟奇·邪眼。",
    [7604] = "如果你愿意接受萨弗隆的设计图，请将瑟银兄弟会契约交给罗克图斯·暗契。",
    [7623] = "从燃烧平原的戈瑟奇那里购买暗影药水。$B$B使用这种药剂进入加德纳尔，然后与魔王贝恩霍勒谈一谈。",
    [7624] = "找到并杀死乌拉泰克，然后把叛徒之心交给加德纳尔的魔王贝恩霍勒。",
    [7625] = "从乌尔丹那里购买克索诺斯星尘，把它交给燃烧平原的戈瑟奇·邪眼。",
    [7626] = "把10瓶暗影之力药剂交给燃烧平原的戈瑟奇·邪眼。",
    [7627] = "把6份大块魔光碎片和25块黑铁矿石交给燃烧平原的戈瑟奇·邪眼。",
    [7628] = "把35块黑龙鳞片交给燃烧平原的戈瑟奇·邪眼。",
    [7629] = "把瓶中的小鬼带到通灵学院的炼金实验室中。在小鬼制造出羊皮纸之后，把瓶子还给戈瑟奇·邪眼。",
    [7630] = "把3块奥金锭交给燃烧平原的戈瑟奇·邪眼。",
    [7631] = "阅读莫苏尔的指南，并召唤出一匹克索诺斯恐惧战马，击败它，然后控制它的灵魂。",
    [7632] = "找到远古石叶的主人。祝你好运，$N。这个世界是很大的。",
    [7634] = "费伍德森林的古树哈斯塔特要求你带回一块成年蓝龙的肌腱。",
    [7635] = "费伍德森林的古树斯托玛要求你带给他一块成年黑龙的肌腱。",
    [7636] = "你必须找到并干掉下列4个恶魔：$B$B迷人的西蒙妮。$B$B疯狂的克林弗兰。$B$BS屠杀者索伦诺尔。$B$B摧毁者阿托留斯。$B$B杀掉这些恶魔，然后回到费伍德森林的古树瓦特鲁斯那里去。$B$B根据你背包中的石化树皮来找到它们所在位置的线索。$B$B你必须独自完成这个任务。",
    [7637] = "到铁炉堡去找高阶牧师洛汉，从他那里拿到驱魔香炉。你需要捐赠150金币来获得它。",
    [7638] = "与暴风城教堂区的格雷森·沙东布瑞克公爵谈一谈。",
    [7639] = "把驱魔香炉交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
    [7640] = "使用驱魔香炉召唤恐惧谷中的灵魂。当你杀掉25个恐惧谷的灵魂之后，回到暴风城教堂区的格雷森·沙东布瑞克公爵那里复命。",
    [7641] = "与暴风城矮人区的格瑞曼德·艾尔默谈一谈。",
    [7642] = "把40块符文布、6块奥金锭、10棵阿尔萨斯之泪、5瓶斯坦索姆圣水和150枚金币交给暴风城矮人区的格瑞曼德·艾尔默。",
    [7643] = "你需要特殊的饲料来喂养灵魂马。南海镇的梅丽德丝·卡尔森可以为你提供这样的粮草。$B$B到菲拉斯的厄运之槌去，杀掉特迪斯·扭木，释放上古圣马之魂。用特殊的粮草喂养它，这样可以安抚它的灵魂。最后，把奥金马铠交给它就可以完成祝福。",
    [7644] = "将被祝福的奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
    [7645] = "把制作魔法粮草所需要的重要材料：20块可口的魔法点心带给希尔斯布莱德丘陵的梅丽德丝·卡尔森。据说银色黎明会出售这种饼干。$B$B你还需要给她50金币来对她进行安抚。",
    [7646] = "把一块艾泽拉斯钻石和一块原始黑钻石交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
    [7647] = "在通灵学院尸骨储藏所地下室的中心使用预言水晶球。将你要审判的灵魂引领出来。将这些灵魂击败然后死亡骑士达克雷尔就将被召唤出来。将其击败然后获得堕落战马的灵魂。$B$B把赎罪的战马之魂和被祝福的奥金马铠一起附在达克雷尔的堕落战马身上。",
    [7648] = "把奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
    [7703] = "找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。$B$B根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。",
    [7761] = "真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。$B$B你从信中获知，达基萨斯将军守卫着烙印。也许你应该就此进行更深入的调查。",
    [7785] = "查看复生之瓶，然后回到德米提恩那里去。",
    [7786] = "如果你想要把逐风者桑德兰从监牢里释放出来，你就必须找到左右两块逐风者禁锢之颅，10块源质锭，以及火焰之王的精华，把它们交给德米提恩。",
    [7787] = "把风吻之刃交给德米提恩。",
    [7877] = "返回图书馆去找到辛德拉的宝藏。拿取你的奖励吧！",
    [8181] = "跟叶基亚谈一谈。",
    [8182] = "跟荆棘谷的莫托尔谈一谈。",
    [8323] = "隐士奥泰尔要你带回10张暮光密文信。",
    [8410] = "为捕风者巴斯拉收集一份空气样本、一份火元素样本、一份土元素样本和一份水元素样本。",
    [8412] = "将灵魂图腾所需的材料交给捕风者巴斯拉。",
    [8921] = "将1个精密奥金转换器、4份强效不灭精华、10瓶石鳞鱼油、25份火山灰和40枚金币交给加基森的穆克斯·玛纳斯卡波。",
    [8922] = "将封起来的血液容器交给加基森的穆克斯·玛纳斯卡波。",
    [8923] = "将封起来的毒液容器交给加基森的穆克斯·玛纳斯卡波。",
    [8924] = "使用灵质提纯器在希利苏斯收集12份烧焦的灵质，在冬泉谷收集12份冰冻的灵质，以及在东瘟疫之地收集12份稳定的灵质。然后将这些东西与灵质提纯器一起交给加基森的穆克斯·玛纳斯卡波。",
    [8925] = "前往燃烧平原，找到熔岩领主博奥克，把它的岩浆核心交给加基森的穆克斯·玛纳斯卡波。",
    [8928] = "到冬泉谷南部的暗语峡谷入口附近去，在那里的一处洞穴内的某个小鬼那里购买一根恶魔元素之杖，并把它交给加基森的穆克斯·玛纳斯卡波。",
    [8929] = "在斯坦索姆的入口处使用超维度幽灵显形器，然后与安泰恩·哈尔蒙的灵魂交谈。",
    [8930] = "在斯坦索姆的入口处使用超维度幽灵显形器，然后与安泰恩·哈尔蒙的灵魂交谈。",
    [8945] = "进入斯坦索姆，从瑞文戴尔男爵手中救出伊思达。",
    [8946] = "将伊思达的盒子交给东瘟疫之地的安泰恩·哈尔蒙。",
    [8947] = "将3块黑铁锭、20张魔化皮、3块月布和4块熟化毛皮交给东瘟疫之地的安泰恩·哈尔蒙。",
    [8948] = "将未完成的挑战之旗交给厄运之槌图书馆内的法尔林·树影。",
    [8949] = "在厄运之槌和黑石塔的食人魔身上收集25串食人魔珠串，然后回去向厄运之槌图书馆内的法尔林·树影复命。",
    [8950] = "将1份游荡鬼灵的精华、4个黑暗符文和8个大块魔光碎片交给厄运之槌图书馆内的法尔林·树影。",
    [8960] = "到黑石山去，使用超维度幽灵显形器找到伯德雷。",
    [8961] = "收集伊森迪奥斯的余炭、艾博希尔灰烬和灰烬公爵的残渣，并从银色黎明军需官那儿购买一只空火盆，然后将这些东西交给黑石山的伯德雷。",
    [8962] = "收集德鲁伊的遗骸，把它们交给黑石山的伯德雷。",
    [8963] = "收集一个星风村遗物，把它交给黑石山的伯德雷。",
    [8964] = "找到一把狂热光芒之剑，把它交给黑石山的伯德雷。",
    [8965] = "拿到放逐者的灵魂灰烬，把它交给黑石山的伯德雷。",
    [8966] = "使用召唤火盆召唤出莫尔·灰蹄的灵魂，然后杀掉他。完成之后，将召唤火盆与瓦塔拉克饰品的左瓣还给黑石山的伯德雷。",
    [8967] = "使用召唤火盆召唤出伊萨利恩的灵魂，然后杀掉她。完成之后，将召唤火盆与瓦塔拉克饰品的左瓣还给伯德雷。",
    [8968] = "使用召唤火盆召唤出亚雷恩和索托斯的灵魂，然后杀掉他们。完成之后，将召唤火盆与瓦塔拉克饰品的左瓣还给黑石山的伯德雷。",
    [8969] = "使用召唤火盆召唤出库尔莫克的灵魂，然后杀掉他。完成之后，将召唤火盆与瓦塔拉克饰品的左瓣还给黑石山的伯德雷。",
    [8970] = "前往尘泥沼泽的奥卡兹岛，从斯塔莎兹纳迦身上收集20份血藻，然后返回黑石山的伯德雷那儿。",
    [8977] = "将超维度幽灵显形器交给铁炉堡的德莉亚娜。",
    [8978] = "将超维度幽灵显形器交给奥格瑞玛的莫克瓦尔。",
    [8985] = "收集一个星风村遗物，把它交给黑石山的伯德雷。",
    [8986] = "收集德鲁伊的遗骸，把它们交给黑石山的伯德雷。",
    [8987] = "找到一把狂热光芒之剑，把它交给黑石山的伯德雷。",
    [8988] = "拿到放逐者的灵魂灰烬，把它交给黑石山的伯德雷。",
    [8989] = "使用召唤火盆召唤出莫尔·灰蹄的灵魂，然后杀掉他。完成之后，将召唤火盆与瓦塔拉克公爵的饰品还给黑石山里的伯德雷。",
    [8990] = "使用召唤火盆召唤出伊萨莉恩的灵魂，然后杀掉他。完成之后，将召唤火盆与瓦塔拉克公爵的饰品还给伯德雷。",
    [8991] = "使用召唤火盆召唤出亚雷恩和索托斯的灵魂，然后杀掉他。完成之后，将召唤火盆与瓦塔拉克公爵的饰品还给黑石山的伯德雷。",
    [8992] = "使用召唤火盆召唤出库尔莫克的灵魂，然后杀掉他。完成之后，将召唤火盆与瓦塔拉克公爵的饰品还给黑石山的伯德雷。",
    [8994] = "从黑石塔的兽人那儿收集40副黑石护腕，把它们和一瓶超级能量合剂一起交给黑石山的伯德雷。",
    [8995] = "在比斯巨兽的房间里使用召唤火盆，召唤瓦塔拉克公爵。杀死他，对尸体使用瓦塔拉克的饰品。然后将瓦塔拉克的饰品还给瓦塔拉克公爵之魂。",
    [8996] = "回到黑石山的伯德雷那里去，把召唤火盆交给他。",
    [8997] = "跟铁炉堡王座大厅内的德莉亚娜谈一谈。",
    [9015] = "到黑石深渊的竞技场去，在你被裁决者格里斯通宣判之后将挑战之旗插在场地中央。杀死塞尔德林和他的角斗士，然后将瓦塔拉克饰品第一部分交给东瘟疫之地的安泰恩·哈尔蒙。",
    [9362] = "为大法师克希雷姆夺回虹彩贝壳。大法师克希雷姆就居住在艾萨拉北部悬崖上的一座塔中。",
    [9364] = "对艾萨拉的恶鞭纳迦使用变形术，然后杀死几秒钟后出现的相似体。当你杀了50个相似体后，回去向大法师克希雷姆复命。",
    [78261] = "找到影牙城堡内的谢尔索斯号角。然后，将它送回至焚木村附近C的秘密投放点。你必须独自完成这项任务。",
    [78676] = "找到血色修道院内的波斯卡之眼。然后将它送回至焚木村附近C的秘密投放点。你必须独自完成这项任务。",
    [79007] = "残存的焦灼纸条是你唯一的向导。",
    [79008] = "残存的焦灼纸条是你唯一的向导。",
    [79192] = "你扯下了木板上的纸条，读着那七扭八歪的字迹。",
    [79229] = "在凄凉之地寻找对遭劫的营地有所了解的人士。",
    [79235] = "寻找凄凉之地劫掠者的成员。",
    [79236] = "将一杯樱桃酒带给藏宝海湾的托卡尔，随后聆听她讲述的故事。",
    [79242] = "在阿拉希高地海岸线上找到伊莱丽·暮羽，并设法打开她存放赃物的储藏箱。",
    [79358] = "为阿拉希高地的维里克·雷锤收集5个扭曲的火焰图腾、5个扭曲的大地图腾、5个扭曲的空气图腾和5个扭曲的水之图腾。",
    [79362] = "去乌鸦岭墓地，从某具骷髅身上找回格兰特的钉锤，然后返回夜色镇，向希拉·沃宁迪打探更多线索。",
    [79363] = "在腐草农场击败7个迪菲亚夜刃和7个迪菲亚附魔师，然后回到夜色镇的希拉·沃宁迪那里了解更多情况。",
    [79974] = "你从泥巴里拖出了一个信使行囊，拂去尘埃后，你发现补给品中夹着一卷羊皮纸。",
    [79975] = "水汽四散，润雾乘风，这番风光不可思议。",
    [79976] = "不管原先谁在这里，你都与其失之交臂。",
    [79980] = "探寻接下来的遭遇。",
    [80411] = "在祖尔法拉克找到卡兹多尔护符，随后带给拉文霍德庄园的法拉德。你必须独自完成任务。",
    [80453] = "将卡兹多尔护符交给拉文霍德庄园地下室的萨恩·刀链。",
    [80454] = "将改装过的护符送到焚木村附近凯乌斯的秘密投放点。",
    [80455] = "回到拉文霍德庄园向法拉德复命。",
    [80526] = "与法拉德交谈，准备聆听他的计划。",
    [84147] = "将15份冬泉谷血样、20枚金币以及一副野性之心护腕交给铁炉堡的德莉亚娜。",
    [84148] = "将15份冬泉谷血样、20枚金币，以及一副野兽追猎者护腕交给铁炉堡的德莉亚娜。",
    [84149] = "将15份冬泉谷血样、20枚金币，以及一副博学者腕轮交给铁炉堡的德莉亚娜。",
    [84150] = "获取15份冬泉谷血液样本和20金币，连同一副光铸护腕一起交给铁炉堡的德莉亚娜。",
    [84151] = "将15份冬泉谷血样、20枚金币，以及一副虔诚护腕交给铁炉堡的德莉亚娜。",
    [84152] = "将15份冬泉谷血样、20枚金币，以及一副迅影护腕交给铁炉堡的德莉亚娜。",
    [84153] = "获取15份冬泉谷血液样本和20金币，连同一副鬼雾护腕一起交给铁炉堡的德莉亚娜。\\n",
    [84154] = "获取15份冬泉谷血液样本和20金币，连同一副勇气护腕一起交给铁炉堡的德莉亚娜。",
    [84155] = "获取15份希利苏斯毒液样本和20金币，连同一副野性之心护腕一起交给奥格瑞玛的莫克瓦尔。",
    [84156] = "获取15份希利苏斯毒液样本和20金币，连同一副驭兽者护腕一起交给奥格瑞玛的莫克瓦尔。",
    [84157] = "将15份希利苏斯毒液样品、20枚金币以及一副博学者腕轮交给奥格瑞玛的莫克瓦尔。",
    [84158] = "将15份希利苏斯毒液样品、20枚金币以及一副虔诚护腕交给奥格瑞玛的莫克瓦尔。",
    [84159] = "将15份希利苏斯毒液样品、20枚金币以及一副迅影护腕交给奥格瑞玛的莫克瓦尔。",
    [84160] = "将15份希利苏斯毒液样品、20枚金币以及一副元素腕轮交给奥格瑞玛的莫克瓦尔。",
    [84161] = "获取15份希利苏斯毒液样本和20金币，连同一副鬼雾护腕一起交给奥格瑞玛的莫克瓦尔。",
    [84162] = "将15份希利苏斯毒液样品、20枚金币以及一副勇气护腕交给奥格瑞玛的莫克瓦尔。",
    [84163] = "将一条野性之心腰带和一副野性之心手套交给铁炉堡的德莉亚娜。",
    [84164] = "将一条驭兽者腰带和一副驭兽者手套交给铁炉堡的德莉亚娜。",
