    [97183] = "带着被祝福的奥金马铠回到提瑞斯法林地班达里安堡的丹妮莎·莫尔那里。",
    [97184] = "把一颗艾泽拉斯钻石和一颗无瑕的黑钻石交给提瑞斯法林地班达里安堡的丹妮莎·莫尔。",
    [97185] = "在通灵学院大藏骨堂地下室的中心使用预言水晶球。这样做会召唤出你必须审判的灵魂。击败这些灵魂后，死亡骑士达克雷尔就会现身。击败他，夺回那匹陨落战马失落的灵魂。$B$B把惩戒之魂和被祝福的魔法马铠交给达克雷尔的陨落战马。",
    [97186] = "为东瘟疫之地的纳萨诺斯·凋零者取回20块强化法力饼干。众所周知，银色黎明是这种饼干的唯一供应者。你还需要付给凋零者50金币作为他的辛苦费。",
    [97197] = "勇闯黑石深渊，为莫高雷的阿拉娜·风暴行者带回一份火焰之地碎片。",
    [97198] = "从黑喉要塞夺回一个黑喉仪祭图腾。",
    [97243] = "把眠炎火炬交给阵风浆果低地烈焰神殿里的奥拉里安·迅燃。",
    [97244] = "在阵风浆果低地消灭天空祭司法拉迪尔，并收集法拉迪尔的徽记。",
    [97245] = "在申达尔高地找到库拉玛的家，并在战斗中击败这个灵魂。获胜后，把库拉玛的面具交给阵风浆果低地的奥拉里安·迅燃。",
    [97250] = "消灭在尘泥沼泽边境侵入贫瘠之地的联盟士兵，然后返回陶拉祖营地向步兵劳格玛复命。",
    [97257] = "在祭祀火盆旁等待奥拉里安开始仪式，并遵循他的指示。",
    [97288] = "把憎恶头颅带给幽暗城的大药剂师法拉尼尔。",
    [97289] = "将男爵的头颅带到幽暗城中奥斯玛尔的躯体旁。",
    [97290] = "将你的发现汇报给幽暗城的大药剂师法拉尼尔。",
    [97291] = "为幽暗城的大药剂师法拉尼尔收集药材：去贸易区找塔文·格瑞斯特拿一顶剧毒骨帽，在草药学训练师附近采点水疱草，最后去潜行者区找毒药商人买些苦楚精华。",
    [97292] = "替大药剂师法拉尼尔将嘶嘶血清注入奥斯玛尔躯体上方的仪器中。",
    [97327] = "深入黑喉要塞，为艾萨拉埃达拉斯废墟的埃卡尔寻回5个黑喉袋。",
    [97411] = "收集15份希利苏斯毒液样品和20枚金币，连同一副光铸护腕，一并交给奥格瑞玛的莫克瓦尔。",
    [97412] = "将一条光铸腰带和一副光铸护手交给奥格瑞玛的莫克瓦尔。",
    [97413] = "带着一套光铸战靴、光铸腿铠和光铸护肩回到奥格瑞玛的莫克瓦尔那里。",
    [97447] = "收集15份冬泉谷血样和20枚金币，连同一副元素腕轮，一并交给铁炉堡的德莉亚娜。",
    [97448] = "将一条元素束带和一副元素护手交给铁炉堡的德莉亚娜。",
    [97449] = "带着一套元素长靴、元素短裙和元素肩铠回到铁炉堡的德莉亚娜那里。",
    [98094] = "高级执行官达萨利亚要求你，将最新的命令送去交给驻扎在塔伦米尔以南、丹加洛克外围的亡灵哨兵玛索吉。",
    [98095] = "亡灵哨兵玛索吉要你带上三只药剂师小瓶，将它们分别放置在希尔斯布莱德丘陵周围的山峰上，然后回去向他复命。",
    [98096] = "前往艾萨拉的塔伦迪斯营地，找指挥官真歌打听一下科尔达拉·炎刃的下落。",
    [98298] = "把6份狼人残骸交给瑟伯切尔的达拉尔·道恩维沃尔。",
    [98299] = "为瑟伯切尔的达拉尔·道恩维沃尔消灭5名病怏怏的难民和5名哈迦德难民。",
    [98325] = "与军官高图斯交谈，为卡加斯远征军效力。",
    [98340] = "与月光林地永夜港的德迪利特·星焰交谈。",
    [98341] = "在月光林地南部寻找塞利楠的化身，听听它要向你传授哪些关于驭风巨豹本性的知识。",
    [98342] = "从怒风兽穴找回尖牙圣物、利爪圣物和静影圣物，并将它们交给巨豹之灵。",
    [98362] = "回到雷霆崖，与长者高地的图拉克·符文图腾谈一谈。",
    [98393] = "与月光林地永夜港的德迪利特·星焰交谈。",
    [98394] = "寻找月光林地南部的巨豹之灵，听它讲述猎豹的天性。",
    [98396] = "从怒风兽穴找回尖牙圣物、利爪圣物和静影圣物，并将它们交给巨豹之灵。",
    [98397] = "回到达纳苏斯，与塞纳里奥区的玛斯雷·驭熊者谈一谈。",
    [98404] = "从怒风兽穴找回尖牙圣物、利爪圣物和静影圣物，并将它们交给塞利楠的化身。",
    [98405] = "寻找月光林地南部的巨豹之灵，听它讲述猎豹的天性。",
    [98447] = "为夜色镇的希拉·沃宁迪查明乌鸦岭瓦洛尔家族鬼魂出没的原因。",
    [98512] = "在申达尔高地消灭10名奥拉凯斯刺客。",
    [98517] = "向泽风岛的塞萨瑞亚·漫空或阿诺尔·风暴打击报到，继续你的萨满祭司训练。$B$B你可以搭乘停靠在莫高雷观天者台地——雷霆崖西北方——的驭空者运输工具返回泽风岛。",
    [98731] = "到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。",
    [98738] = "到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。",
    [98739] = "与丹德莱特交谈。",
    [98830] = "将托塞德林的破碎战刃交给厄运之槌的辛德拉古灵。",
    [99257] = "杀死一个衰朽的水晶塔守护者，取得它的耗竭的水晶之心，把它交给辛德拉神殿中的历史学家比拉克萨斯。",
    [99258] = "把耗竭的水晶之心扔进一道不稳定的法力裂隙中。带着成功或失败的证据回到辛德拉神殿中的历史学家比拉克萨斯那里。",
    [99260] = "与瓦拉纳尔的伊拉德林·晚风交谈。",
    [99435] = "跟随雷吉纳德·温德索尔元帅在暴风城中前进。保护他，别让他受到伤害！\\n\\n如果你需要再次联系雷吉纳德·温德索尔元帅，请与侍从罗维交谈。",
    [99670] = "回到宁静摇篮的杰勒曼那里。",
}
